  'limport.title': 'رفع العروض دفعة واحدة',
  'limport.subtitle': 'CSV أو Excel — صف واحد لكل دفعة. يُتحقق من كل صف قبل إنشاء أي شيء؛ الصف السيئ لا يمنع الصفوف الجيدة أبدًا.',
  'limport.trustPath': 'العروض المنشأة دفعة واحدة تسلك المسار العادي: مسودة ← موافقة العضو ← مراقبة الجودة ← منشور. الرفع الجماعي يسرّع الإدخال، ولا يتخطى الثقة أبدًا — لا يصل شيء من هنا إلى مشترٍ دون موافقة مراجع.',
  'limport.consentNote': 'كل صف يعرض منتجات شخص آخر، لذلك يجب أن يكون كل عضو قد سجّل موافقته على البيع نيابةً عنه (بالصوت أو بنقرة في التطبيق). الصفوف التي تفتقر إليها تُعلَّم للتصحيح، ولا تُحذف بصمت أبدًا — منتجاتهم، وموافقتهم.',
  'limport.kycGap': 'عبارة التصميم «التحقق من الهوية (KYC) معلّق — المسودة مسموحة، والنشر ممنوع حتى التحقق» مبنية جزئيًا عن قصد: المسودة مسموحة فعلًا، لكن لا توجد بوابة تحقق من الهوية عند النشر في أي مكان على هذه المنصة (خريطة التحقق لكل دور تحكم المدفوعات وليس لها غرض في العروض). اختراع بوابة هنا سيطبّق قاعدة على الدفعات المستوردة دون العروض المنشأة من وحدة التحكم — لذلك سُمّي عملًا خلفيًا بدلًا من تزييفه.',
