  'templates.actDone.reject': 'تم الرفض. يقرأ الكاتب ملاحظتك على القالب؛ لا يتغير شيء مما يُرسل.',
  'templates.actDone.withdraw': 'تم السحب. يمكنك كتابة إصدار جديد.',
  'templates.actDone.retire': 'تم الإيقاف. من الإرسال التالي يتلقى أعضاؤك الإعداد الافتراضي للمنصة — أو، حيث لا يوجد، تسجّل تلك القناة "لا يوجد قالب".',
  'templates.refused.sendTest': '"إرسال تجربة إلى هاتفي" غير مبني: لا يوجد في نطاق المستأجر مسار إرسال حقيقي للتجربة عبره (المُرسِل غير متصل هنا)، ورسالة SMS تجريبية بصياغة غير مسجلة لدى DLT سيرفضها المشغّل. المعاينة أدناه هي عرض المنصة نفسها.',
  'templates.refused.experiment': '"تجربة جديدة" غير مبنية: لا يوجد جدول تجارب (DELTA-029) — لا يوجد تقسيم للمتغيرات أو عدد للتعرّض أو فائز لتسجيله.',
  'templates.refused.dltReverify': '"التعديلات تعيد التحقق من DLT قبل الإرسال التالي" من شأن مكتب المنصة: لا يستطيع المستأجر التقديم إلى DLT. الصحيح هنا: تعديل الرسائل القصيرة لا يعمل أبدًا من وحدة التحكم هذه، لذلك تستمر الصياغة السابقة في الإرسال.',
  'templates.refused.deliveryStats': 'غير مقيس هنا: التسليم لكل إصدار قالب غير مسجل، وسجل التسليم في تعاونيتك صفحة مستقلة (لم تُبنَ بعد).',
  'templates.refused.draftHistoryCanon': 'المسودات إصدارات: يُحتفظ بكل واحد منها، مع من كتبه ومن بتّ فيه.',
  'templates.refused.compiledCache': 'لا يوجد "تخزين مؤقت مُجمَّع": الإرسال يقرأ الإصدارات المعتمدة من قاعدة البيانات، لذلك الصفحة التي يفشل تحميلها لا تغيّر شيئًا مما يُرسل.',
  'templates.refused.retryPageLoad': '"إعادة المحاولة" هي إعادة تحميل للصفحة، وليست إجراءً: لا يُعاد أي شيء نيابةً عنك.',
