  'res.how.2': 'ورقة الاقتراع: نقرة واحدة؛ يمكن تغيير الصوت حتى إغلاق التصويت، ويصبح نهائيًا بعده.',
  'res.how.3': 'كل ورقة اقتراع خيار يعلنه القرار (مؤيد · معارض · ممتنع)، واحدة لكل عضو — الأسهم تضيف رأس مال، ولا تضيف أصواتًا أبدًا.',
  'res.passes.title': 'إذا أُقرّ',
  'res.passes.body': 'توزيع الأرباح أو مكافأة التعامل يسلك مسارات الأموال العادية: المعادلة في القرار ← مبالغ لكل عضو ← دفعة مدفوعات يُعدّها شخص ويؤكدها آخر ← موافقة مكتب المدفوعات على الدفعة من شخصين. لا يمكن الدفع إلا لقرار نتيجته المسجَّلة "أُقرّ"؛ والتصويت الفاشل لا يمكنه ذلك.',
  'res.footer': 'دورة حياة القرار مُسجَّلة (من فتح، ومن أغلق، ومتى، ولماذا) · الأصوات غير قابلة للتغيير بعد الإغلاق · النتائج تُنشر لكل عضو في التطبيق.',
