  'res.state.flaggedOff.body': 'هذه الوحدة متوقفة لهذه التعاونية (علامة ميزة). لا شيء معطوب — إنها غير مفعَّلة فقط. راجع إعدادات الخطة.',
  'res.state.restricted.title': 'صياغة المسودات مقيّدة',
  'res.state.restricted.body': 'صياغة التصويت وفتحه وإغلاقه تتطلب صلاحية الحوكمة. أما التصويت نفسه فهو حق لكل عضو مؤهل — وحدة التحكم هذه لا تُدلي بأصوات نيابةً عن أحد أبدًا.',
  'res.state.notFound.title': 'القرار غير موجود',
