  'res.state.error.body': 'تعذّرت قراءة القرارات الآن. لم يتغيّر شيء؛ والأصوات المُدلى بها محفوظة.',
  'res.refused.smsVoice': 'لم يُرسل: الرسائل النصية القصيرة والمكالمة الصوتية للأعضاء الذين لا يملكون هواتف ذكية — لا يوجد قالب SMS معتمد ولا مزوّد خدمة صوتية على هذه المنصة.',
  'res.refused.noticePeriod': 'غير مُطبَّق: "14 يومًا قبل الإغلاق، الحد الأدنى في النظام الداخلي" — لا شيء يسجّل وقت إرسال الإشعار، لذا لا يمكن قياس مدة الإشعار.',
  'res.refused.voiceReadout': 'غير مبني: قراءة صوتية لورقة الاقتراع — لا يوجد مزوّد خدمة صوتية.',
  'res.refused.paperBallot': 'غير مبني: البديل الورقي عند منضدة MCC — يجب أن يسجّل التصويت الورقي من أدخله ونيابةً عن من، وهذا السجل غير موجود بعد.',
  'res.refused.board': 'لا يوجد دور لمجلس الإدارة على هذه المنصة: صياغة التصويت وفتحه أو إغلاقه تتم بصلاحية الحوكمة (التي يملكها مسؤول المستأجر).',
  'res.refused.boardElection': 'انتخاب مجلس الإدارة يسمّي مرشحين، ولا توجد قائمة مرشحين على هذه المنصة — لا يمكن صياغته أو التصويت عليه هنا.',
  'res.refused.perLanguageText': 'نص واحد لكل قرار: يُعرض للأعضاء تمامًا كما كُتب — لا توجد نسخة لكل لغة من كلمات القرار نفسه.',
  'res.refused.autoClose': 'يُرفض التصويت تلقائيًا بعد وقت الإغلاق، لكن القرار يُغلقه شخص — الإغلاق يسجّل النتيجة، والنتيجة إجراء مسجَّل لشخص ما.',
  'res.refused.closingSoon': 'لا يُرسل تذكير "يُغلق قريبًا": القواعد تنص على إشعار عند فتح التصويت والنتيجة عند إغلاقه.',
  'res.refused.memberApp': 'تطبيق الأعضاء للهاتف لا يحتوي على شاشة اقتراع بعد — يصوّت الأعضاء من ورقة الاقتراع في وحدة التحكم هذه أثناء تسجيل دخولهم.',
  'res.refused.payoutConsole': 'دفعة المدفوعات (الإعداد، ثم يؤكدها شخص ثانٍ) إجراء عبر API؛ هذه الشاشة لا تعرض زرًا للتشغيل.',
  'res.refused.smsResult': 'رسالة "SMS بالغوجاراتية" عند الدفع لا تُرسل (لا يوجد قالب SMS)؛ يُبلَّغ الأعضاء في التطبيق وبإشعار فوري.',
