  'swd.code.NOT_FOUND': 'غير موجود.',
  'swd.code.unknown': 'فشل الإجراء لسبب لا تتعرف عليه وحدة التحكم.',
  'swd.agm.method.gmv': 'GMV = قيمة البضائع (المجموع الفرعي للطلب، قبل التوصيل والرسوم والضريبة) لكل طلب اكتمل خلال السنة المالية. لا تُحتسب الطلبات المستردة أو الملغاة بعد اكتمالها. المصدر: الطلبات.',
  'swd.agm.method.paid_to_members': 'المدفوع للأعضاء = صافي القيود المرحّلة إلى المحافظ الرئيسية للأعضاء ضمن escrow_release خلال السنة: تسويات الطلبات قيود دائنة، واستردادات النزاعات والمرتجعات قيود مدينة. المصدر: دفتر الأستاذ.',
  'swd.agm.method.paid_share': 'الحصة = المدفوع للأعضاء مقسومًا على GMV، وكلاهما معروض، بالعملة نفسها (نقاط أساس، مقرّبة للأسفل). نسبة بين حقيقتين.',
  'swd.agm.method.platform_fees': 'رسوم المنصة = الصافي المرحّل إلى حساب رسوم المنصة من تسويات طلبات هذه التعاونية واستردادتها خلال السنة. المصدر: دفتر الأستاذ.',
  'swd.agm.method.gst_on_commission': 'GST على العمولة = الصافي المرحّل إلى حساب GST المستحق للمنصة من تسويات طلبات هذه التعاونية خلال السنة. المصدر: دفتر الأستاذ.',
  'swd.agm.method.tenant_commission': 'عمولة التعاونية = الصافي المرحّل إلى حساب العمولة الخاص بهذه التعاونية من تسويات طلباتها خلال السنة. المصدر: دفتر الأستاذ.',
  'swd.agm.method.surplus': 'فائض FPO مرفوض: المنصة لا تحتفظ بدفتر لتكاليف تشغيل التعاونية، لذا لا يمكن حساب الفائض من الحقائق. راجع الحسابات المدققة.',
  'swd.agm.method.operating_costs': 'تكاليف التشغيل مرفوضة: لا يوجد دفتر تكاليف على المنصة. دفاتر التعاونية الخاصة (ومدققها) هي المصدر.',
  'swd.agm.method.statements': 'كشوف التسوية التي تتداخل فترتها مع السنة المالية، الصادرة للأعضاء. يقرأ كل عضو كشفه في صفحة الكشوف.',
  'swd.agm.method.snapshot': 'سجل الأسهم في نهاية السنة: الصفوف التي كانت موجودة حينها ولم تتغير منذ ذلك الوقت. إذا تغيّر أي منها، يُرفض المستخرج — السجل لا يحتفظ بالتاريخ.',
  'swd.agm.method.closed_in_fy': 'القرارات المغلقة خلال السنة المالية، مع النتيجة المسجلة عند الإغلاق (النصاب والأغلبية كما سُجّلا حينها).',
  'swd.agm.method.annexure': 'تقرير المدقق كما رفعته التعاونية — لم تُنتجه المنصة ولم تفحصه.',
  'swd.agm.method.quorum': 'النصاب كما هو مسجل في الإعداد governance.quorum_bp (الخاص بالتعاونية، أو افتراضي المنصة إن لم يكن لديها إعداد).',
  'swd.agm.method.notice_period': 'مدة إشعار AGM مرفوضة: لا يوجد إعداد لها في النظام الداخلي على المنصة، والرقم من الذاكرة ليس بيانات.',
